/** Rickshaw-paint-inspired community homepage. Uses the existing demo store. */
export function renderRickshawHome(ctx,tx){
 const {store,esc,icon,formatDate,money}=ctx,s=store.getState();
 const events=s.events.filter(e=>e.status==='published').slice(0,3);
 const members=s.members.filter(m=>m.directoryVisible&&m.status==='approved').slice(0,3);
 const foodEvent=s.events.find(e=>e.status==='published'&&e.foodEnabled);
 const food=s.menu.filter(i=>i.eventId===foodEvent?.id).slice(0,3);
 const gallery=s.gallery.slice(0,3);
 const more=(en,bn)=>`${tx(en,bn)} ${icon('arrowUp')}`;
 const initials=name=>esc(name.split(' ').map(n=>n[0]).slice(0,2).join(''));
 return `<div class="rk-home">
 <section class="rk-hero" data-parallax aria-labelledby="rk-hero-title">
  <div class="rk-hero-corners" aria-hidden="true"></div>
  <div class="rk-hero-topline"><span>${tx('TOKYO INTERNATIONAL UNIVERSITY','টোকিও ইন্টারন্যাশনাল ইউনিভার্সিটি')}</span><span class="rk-origin"><i></i> DHAKA ROOTS <b>↔</b> TOKYO DREAMS</span></div>
  <div class="rk-hero-stage"><div class="rk-hero-copy"><p class="rk-kicker"><span>✽</span> ${tx('OUR PEOPLE. OUR LITTLE PIECE OF HOME.','আমাদের মানুষ। আমাদের আপন ঠিকানা।')}</p><h1 id="rk-hero-title">${tx('A little<br><span class="rk-painted-word">Bangladesh.</span><br><em>A lot of heart.</em>','একটু<br><span class="rk-painted-word rk-bn-title">বাংলাদেশ।</span><br><em>অনেক আপনজন।</em>')}</h1><p class="rk-hero-description">${tx('A familiar feeling, a thousand miles from home. We’re a community of Bangladeshi students, alumni, and friends — bringing our colours to life in Japan.','দেশ থেকে দূরে, তবু পরিচিত এক অনুভূতি। আমরা বাংলাদেশি শিক্ষার্থী, অ্যালামনাই ও বন্ধুরা—জাপানে আমাদের রঙে রাঙাই একসাথে পথচলা।')}</p><div class="rk-hero-actions"><a class="btn rk-btn-painted" href="#/join">${more('Find your people','আমাদের সঙ্গী হোন')}</a><a class="rk-underlined" href="#/events">${more('What’s happening','আয়োজন দেখুন')}</a></div><div class="rk-hero-signoff"><span lang="bn">একসাথে, আরও দূরে।</span><small>ROOTED IN CULTURE. OPEN TO EVERYONE.</small></div></div>
  <div class="rk-hero-art"><div class="rk-art-orbit" aria-hidden="true"></div><div class="rk-art-label" aria-hidden="true"><span class="rk-art-label-ring"></span><strong lang="bn">মনের<br>টানে</strong><small>A LITTLE DESH</small></div><figure class="rk-rickshaw-figure"><img src="assets/rickshaw-hero-v2.webp" width="1536" height="1024" alt="Original hand-painted Dhaka rickshaw with peacocks, roses, a pink canopy and blue wheels" fetchpriority="high"><figcaption>WITH LOVE, FROM OUR ROOTS <span>↗</span></figcaption></figure><img class="rk-floating-flower" src="assets/rickshaw-flower.svg" alt="" aria-hidden="true" width="90" height="90"></div></div>
  <div class="rk-hero-bottom"><a href="#/about"><span>01</span> ${tx('CULTURE IN OUR HEARTS','হৃদয়ে আমাদের সংস্কৃতি')} <b>✽</b></a><a href="#/community"><span>02</span> ${tx('COMMUNITY BY OUR SIDE','পাশে আমাদের মানুষ')} <b>✽</b></a><a href="#/alumni"><span>03</span> ${tx('A FUTURE WE SHARE','একসাথে আগামীর পথে')} <b>✽</b></a><button class="rk-motion-toggle" data-motion-toggle type="button" aria-pressed="false"><span aria-hidden="true">Ⅱ</span><span data-motion-label>Pause motion</span></button></div>
 </section>
 <div class="rk-painted-trim" aria-hidden="true"></div>
 <div class="rk-marquee" aria-label="Bangladesh in our hearts, Japan in our everyday"><div class="rk-marquee-track"><span>বাংলাদেশ হৃদয়ে <i>✳</i> JAPAN IN OUR EVERYDAY <i>✳</i> GOOD PEOPLE. GREAT ADDA. <i>✳</i> একসাথে আরও দূরে <i>✳</i></span><span aria-hidden="true">বাংলাদেশ হৃদয়ে <i>✳</i> JAPAN IN OUR EVERYDAY <i>✳</i> GOOD PEOPLE. GREAT ADDA. <i>✳</i> একসাথে আরও দূরে <i>✳</i></span></div></div>
 <section class="rk-section rk-gatherings" aria-labelledby="rk-gatherings-title"><header class="rk-section-heading" data-reveal><div><p class="rk-kicker"><span>✽</span> ${tx('MEET YOU THERE','দেখা হবে আয়োজনে')}</p><h2 id="rk-gatherings-title">${tx('Good company.<br><em>Even better memories.</em>','ভালো সঙ্গ।<br><em>রঙিন সব স্মৃতি।</em>')}</h2></div><a class="rk-underlined" href="#/events">${more('All gatherings','সব আয়োজন')}</a></header>
 <div class="rk-event-grid">${events.map((e,i)=>`<article class="rk-event-ticket rk-ticket-${i}" data-reveal data-tilt><a class="rk-event-poster" href="#/events/${esc(e.slug)}"><img src="${esc(e.image)}" alt="${esc(e.title)} illustrated event poster" loading="lazy"><span class="rk-event-category">${esc(e.category)}</span><span class="rk-event-open">${icon('arrowUp')}</span></a><div class="rk-event-ticket-body"><div class="rk-event-date"><span>${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'short'})}</span><strong>${new Date(e.date+'T12:00:00').getDate()}</strong><small>${e.date.slice(0,4)}</small></div><div class="rk-event-title"><span class="rk-sample">SAMPLE GATHERING</span><h3><a href="#/events/${esc(e.slug)}">${esc(e.title)}</a></h3><p>${icon('pin')} ${esc(e.location)}</p><p>${icon('clock')} ${esc(e.time)} JST</p></div></div><div class="rk-ticket-stub"><span>${e.price?money(e.price):'Free entry'} ${e.foodEnabled?'· Food & friends':''}</span><a href="#/events/${esc(e.slug)}">Save your place ${icon('arrowUp')}</a></div></article>`).join('')||'<div class="empty-state">New gatherings will appear here.</div>'}</div><p class="rk-footnote">${icon('info')} Preview events to explore the experience. Official gatherings will be announced by TIU BSS.</p></section>
 <section class="rk-story"><div class="rk-story-inner"><div class="rk-story-collage" data-reveal data-parallax><span class="rk-tape rk-tape-one" aria-hidden="true"></span><figure class="rk-story-frame"><img src="assets/reference-peacocks.webp" alt="Traditional Bangladeshi rickshaw art with vivid flowers and blue peacocks" loading="lazy"><figcaption>রঙে রঙে, আপন গল্পে।</figcaption></figure><div class="rk-story-note"><span>✽</span><p>Different journeys.<br><em>The same roots.</em></p><small>বাংলাদেশ থেকে, ভালোবাসায়</small></div><img class="rk-story-flower" src="assets/rickshaw-flower.svg" width="135" height="135" alt="" aria-hidden="true"></div><div class="rk-story-copy" data-reveal><p class="rk-kicker"><span>✽</span> ${tx('A PLACE THAT FEELS LIKE US','আমাদের মতো আপন ঠিকানা')}</p><h2>${tx('Some things<br>just feel<br><em>like home.</em>','কিছু অনুভূতি<br>সবসময়ই<br><em>ঘরের মতো।</em>')}</h2><p>${tx('The first spoon of biryani. A song everyone knows. An adda that goes on a little too long. Home travels with us — in the things we share and the people we find.','বিরিয়ানির প্রথম স্বাদ। সবার চেনা গান। একটু বেশি সময় ধরে চলা আড্ডা। ভাগ করে নেওয়া গল্প আর আপন মানুষেই খুঁজে পাই ঘর।')}</p><div class="rk-story-values"><div><b>01 /</b><span>Celebrate our culture</span></div><div><b>02 /</b><span>Show up for each other</span></div><div><b>03 /</b><span>Make room to grow</span></div></div><a class="rk-underlined" href="#/about">${more('The story we’re building','আমাদের পথচলার গল্প')}</a></div></div></section>
 <section class="rk-food-section"><div class="rk-food-header" data-reveal><div><p class="rk-kicker"><span>✽</span> ${tx('COME HUNGRY. LEAVE HAPPY.','খাবারের টানে, আড্ডার আসরে')}</p><h2>${tx('A taste of <em>home.</em>','ঘরের <em>স্বাদ।</em>')}</h2></div><span class="rk-food-bangla" lang="bn" aria-hidden="true">আহা! কী স্বাদ!</span></div><div class="rk-food-layout"><div class="rk-food-intro" data-reveal><span class="rk-food-sticker">GOOD FOOD<br><b>GOOD MOOD</b><span>✷</span></span><p>From a proper plate of biryani to that first tangy bite of fuchka. Order at the event. Pick up at the counter. Get back to the adda.</p>${foodEvent?`<a class="btn rk-btn-painted rk-btn-yellow" href="#/events/${esc(foodEvent.slug)}/food">Explore the food table ${icon('arrowUp')}</a>`:'<a class="btn rk-btn-painted rk-btn-yellow" href="#/events">Explore gatherings ↗</a>'}<small>Sample menu · Cash due at pickup</small></div><div class="rk-food-teasers">${food.map((f,i)=>`<a class="rk-food-teaser rk-food-${i}" data-reveal href="#/events/${esc(foodEvent.slug)}/food"><div class="rk-food-dish"><img src="${esc(f.image)}" alt="${esc(f.name)} illustration" loading="lazy"><span>${icon('arrowUp')}</span></div><h3>${esc(f.name)}</h3><p>${esc(f.nameBn||f.category)}</p><strong>${money(f.price)}</strong></a>`).join('')}</div></div></section>
 <section class="rk-section rk-people-section"><header class="rk-section-heading" data-reveal><div><p class="rk-kicker"><span>✽</span> ${tx('IT’S THE PEOPLE WHO MAKE THE PLACE','মানুষেই আপন ঠিকানা')}</p><h2>${tx('Different paths.<br><em>One big community.</em>','পথ ভিন্ন।<br><em>আপনজন সবাই।</em>')}</h2></div><a class="rk-underlined" href="#/community">${more('Meet our people','আমাদের মানুষ')}</a></header><div class="rk-member-grid">${members.map((m,i)=>`<article class="rk-member-card rk-member-${i}" data-reveal data-tilt><div class="rk-member-ribbon"><span>TIU BSS / COMMUNITY CARD</span><b>✽</b></div><div class="rk-member-id"><span class="rk-avatar">${initials(m.name)}</span><span class="rk-member-category">${esc(m.type)}<small>${esc(m.city)}</small></span></div><h3>${esc(m.name)}</h3><p>${esc(m.jobTitle||m.major)}</p><p class="rk-member-place">${esc(m.employer||m.university)}</p><div class="rk-member-skills">${(m.skills||[]).slice(0,2).map(skill=>`<span>${esc(skill)}</span>`).join('')}</div><div class="rk-member-bottom"><span>DEMO PROFILE</span><a href="#/members/${esc(m.id)}" aria-label="Meet ${esc(m.name)}">${icon('arrowUp')}</a></div></article>`).join('')}</div><div class="rk-mentorship-note" data-reveal><img src="assets/rickshaw-bird.svg" alt="" width="100" height="100" aria-hidden="true"><p>Your experience could be<br><em>someone else’s beginning.</em></p><a class="rk-underlined" href="#/mentorship">Explore mentorship ${icon('arrowUp')}</a></div></section>
 <section class="rk-gallery-section"><header class="rk-section-heading" data-reveal><div><p class="rk-kicker"><span>✽</span> ${tx('A COLOURFUL PIECE OF US','আমাদের রঙিন গল্প')}</p><h2>${tx('All our colours.<br><em>All our stories.</em>','আমাদের রং।<br><em>আমাদের গল্প।</em>')}</h2></div><a class="rk-underlined" href="#/gallery">${more('Step inside the gallery','গ্যালারি দেখুন')}</a></header><div class="rk-artwall">${gallery.map((g,i)=>`<button class="rk-artprint rk-artprint-${i}" data-global="gallery" data-id="${esc(g.id)}" data-reveal aria-label="View ${esc(g.title)}"><div class="rk-artprint-image"><img src="${esc(g.image)}" alt="${esc(g.caption||g.title)}" loading="lazy"><span>${icon('arrowUp')}</span></div><div class="rk-artprint-caption"><small>0${i+1} / ${esc(g.category)}</small><h3>${esc(g.title)}</h3></div></button>`).join('')}</div><p class="rk-footnote">Artwork references & original illustrations. Community photographs can be added from the admin workspace.</p></section>
 <section class="rk-final-cta" data-parallax><div class="rk-final-frame"><img class="rk-cta-vine rk-cta-vine-left" src="assets/rickshaw-vine.svg" alt="" aria-hidden="true"><img class="rk-cta-vine rk-cta-vine-right" src="assets/rickshaw-vine.svg" alt="" aria-hidden="true"><div data-reveal><p class="rk-kicker">${tx('COME AS YOU ARE. BELONG AS YOU ARE.','যেমন আপনি, তেমনই আপন।')}</p><p class="rk-cta-bn" lang="bn">একসাথে, আরও দূরে।</p><h2>${tx('There’s a place<br>for you here.','এখানেই আপনার<br>আপন ঠিকানা।')}</h2><p>Student. Alumnus. Friend. A new chapter begins with a hello.</p><a class="btn rk-btn-painted rk-btn-yellow" href="#/join">${more('Come be part of it','আমাদের সঙ্গী হোন')}</a></div></div><span class="rk-cta-side" aria-hidden="true">FROM BANGLADESH, WITH LOVE.</span></section>
 </div>`;
}
